    def reconnect(self, request):
        """
        处理重连接获取user_token的业务
        :param request: dict 失效前的请求字典
        :return: error_dict: dict 错误信息
                  request: dict 新的请求字典
        """
        if self.future_counter_type == 'CTP':
            self.connector_manager.DestroyConnect()
        returninfo = self.init_connection()
        error_no = returninfo['error_no']
        if error_no != SUCCESS:
            return (returninfo, {})
        else:
            error_dict, response = self.login_account(op_branch_no=self.branch_no, op_entrust_way=self.entrust_way, op_station=self.op_station, password=self.password, account_content=self.operator_no, content_type=self.content_type, input_content='1')
            if error_dict['error_no'] == SUCCESS:
                request['user_token'] = self.user_token
            return (error_dict, request)
    def future_order_response_transform(self, list_result):
        data_list = []
        if self.future_counter_type == 'UFT':
            NotB_list = ['entrust_no', 'futures_account', 'futu_exch_type', 'futu_code', 'entrust_bs', 'futures_direction', 'hedge_type', 'fund_account', 'report_id', 'firm_id', 'operator_no', 'client_group', 'entrust_amount', 'total_business_amount', 'withdraw_amount', 'futu_entrust_price', 'entrust_status', 'branch_no', 'batch_no', 'entrust_type', 'amount_per_hand', 'forcedrop_reason', 'init_date', 'entrust_time', 'confirm_id', 'entrust_occasion', 'futu_entrust_price2', 'entrust_prop', 'arbit_code', 'entrust_reference', 'error_message', 'position_str', 'session_no', 'second_code', 'weave_type', 'delta_entrust_fare', 'delta_entrust_margin', 'delta_entrust_premium', 'withdraw_reference', 'time_condition', 'volume_condition', 'delta_report_fare', 'fex_min_volume', 'withdraw_reason_type', 'curr_date']
            QH_btytes = list_result[0]['QH'].encode('utf-8')
            QH_blist = QH_btytes.split(b'\x01')
            QH_dict = {}
            QH_blist.pop()
            for i in range(45):
                QH_dict[NotB_list[i]] = QH_blist[i].decode('utf-8')
            else:
                QH_list_result = [QH_dict]
        else:
            QH_list_result = list_result
        for item in QH_list_result:
            entrust_bs = item.get('entrust_bs')
            if entrust_bs == '1':
                amount = int(float(item.get('entrust_amount')))
            elif entrust_bs == '2':
                amount = -int(float(item.get('entrust_amount')))
            else:
                amount = 0
            order_time = del_order_time(str(item.get('entrust_time', '')))
            stock_code = f"{item.get('futu_code')!s}.{EXCHANGE_TYPES_DICT_REVERT[item.get('futu_exch_type')]!s}"
            error_info = item.get('error_message', '')
            if '客户交易密码错误' in error_info or len(re.findall(self.password_re, error_info)) > 0:
                if self.trade_id is not None:
                    set_trade_stop_status(self.trade_id)
                    strategy_log.error('客户交易密码错误，终止交易')
                    raise
                error_info = error_info.replace('错误', '错误，交易即将关闭')
            elif len(re.findall(self.token_re, error_info)) > 0:
                error_info = error_info + '，交易即将关闭'
            data_item = {'entrust_no': item.get('entrust_no_s') if item.get('entrust_no_s', '') != '' else item.get('entrust_no'), 'order_time': order_time, 'stock_code': stock_code, 'amount': amount, 'price': float(item.get('futu_entrust_price')), 'status': item.get('entrust_status'), 'business_amount': int(float(item.get('total_business_amount', 0))), 'error_info': error_info, 'entrust_type': item.get('entrust_type'), 'entrust_prop': item.get('entrust_prop'), 'entrust_reference': item.get('entrust_reference')}
            data_list.append
        else:
            return data_list
    def future_trade_response_transform(self, list_result):
        data_list = []
        if self.future_counter_type == 'UFT':
            B_list = ['entrust_no', 'futures_account', 'futu_exch_type', 'business_id', 'futu_code', 'entrust_bs', 'futures_direction', 'futu_business_price', 'business_amount', 'hedge_type', 'fund_account', 'report_id', 'firm_id', 'operator_no', 'client_group', 'entrust_amount', 'total_business_amount', 'withdraw_amount', 'futu_entrust_price', 'entrust_status', 'branch_no', 'batch_no', 'entrust_type', 'amount_per_hand', 'forcedrop_reason', 'init_date', 'business_time', 'confirm_id', 'entrust_occasion', 'futu_entrust_price2', 'entrust_prop', 'arbit_code', 'entrust_reference', 'position_str', 'session_no', 'delta_entrust_fare', 'delta_business_fare', 'delta_entrust_margin', 'delta_hold_margin', 'delta_entrust_premium', 'delta_premium', 'delta_drop_income', 'delta_drop_income_float', 'curr_date']
            data_list = []
            QH_btytes = list_result[0]['QH'].encode('utf-8')
            QH_blist = QH_btytes.split(b'\x01')
            QH_dict = {}
            QH_blist.pop()
            for i in range(44):
                QH_dict[B_list[i]] = QH_blist[i].decode('utf-8')
            else:
                QH_list_result = [QH_dict]
        else:
            QH_list_result = list_result
        for item in QH_list_result:
            status = item.get('entrust_status')
            if item.get('entrust_bs') == '1':
                amount = int(float(item.get('business_amount', 0)))
            elif item.get('entrust_bs') == '2':
                amount = -int(float(item.get('business_amount', 0)))
            else:
                amount = 0
            business_price = float(item.get('futu_business_price', 0))
            date_str = str(item.get('init_date'), '0')
            if date_str == '0':
                date_str = datetime.datetime.now().strftime('%Y%m%d')
            business_time = del_order_time(str(item.get('business_time', '')), date_str)
            stock_code = f"{item.get('futu_code')!s}.{EXCHANGE_TYPES_DICT_REVERT[item.get('futu_exch_type')]!s}"
            withdraw_no = str(item.get('withdraw_no', '0'))
            data_item = {'entrust_no': str(item.get('entrust_no_s') if item.get('entrust_no_s', '') != '' else item.get('entrust_no')), 'business_time': business_time, 'stock_code': stock_code, 'entrust_bs': item.get('entrust_bs'), 'business_amount': amount, 'business_price': business_price, 'business_balance': amount * business_price * int(float(item.get('amount_per_hand', 0))), 'business_id': item.get('business_id'), 'status': status, 'cancel_info': item.get('cancel_info', ''), 'withdraw_no': withdraw_no, 'real_type': item.get('real_type'), 'real_status': item.get('real_status'), 'entrust_reference': item.get('entrust_reference')}
            data_list.append
